    col = cell(e["alpha"])
    row = (W - 1) - cell(e["beta"])  # invert so larger beta = top
    sym = pillar_symbol[e["pillar"]]
    if e["name"] == HKM_NAME:
        sym = "H"
    cur = grid[row][col]
    if priority[sym] < priority.get(cur, priority["."]):
        grid[row][col] = sym

